        vm.startPrank(tester);
        _gameItemsContract.mint(0, 1);
        assertEq(_gameItemsContract.balanceOf(tester, 0), 1);
        vm.expectRevert();
        _gameItemsContract.safeTransferFrom(tester, testerTwo, 0, 1, "");

