        _gameItemsContract.safeBatchTransferFrom(tester, testerTwo, ids, amounts, "");
        assertEq(_gameItemsContract.balanceOf(tester, 0), 0);
        assertEq(_gameItemsContract.balanceOf(testerTwo, 0), 1);
    }
```

