    uint256 element,
    uint8 generation
) 
    public 
{
    emit FighterCreated(id, weight, element, generation);

    // Critical bug: Unintentional reentrancy vulnerability
    if (generation == 1) {
        // Call an external contract which might call back into this contract
        // causing unexpected behavior or reentrancy attack
        someExternalContract.someFunction();
    }
}


